n = int(input())
eng_bosh = 1
eng_qadam = 0
for bosh in range(2, n):
    x = bosh
    qadam = 0
    while x != 1:
        if x % 2 == 0:
            x //= 2
        else:
            x = 3 * x + 1
        qadam += 1
    if qadam > eng_qadam:
        eng_qadam = qadam
        eng_bosh = bosh
print(eng_bosh, eng_qadam)

starter.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int engBosh = 1;
        long engQadam = 0;
        for (int bosh = 2; bosh < n; bosh++) {
            long x = bosh;
            long qadam = 0;
            while (x != 1) {
                if (x % 2 == 0) x /= 2;
                else x = 3 * x + 1;
                qadam++;
            }
            if (qadam > engQadam) {
                engQadam = qadam;
                engBosh = bosh;
            }
        }
        System.out.println(engBosh + " " + engQadam);
    }
}

